import numpy as np
import matplotlib.pyplot as plt

class Drone:
    def __init__(self, x, y, z):
        self.x = x
        self.y = y
        self.z = z
        self.velocity_x = 0
        self.velocity_y = 0
        self.velocity_z = 0

    def fly(self):
        self.x += self.velocity_x
        self.y += self.velocity_y
        self.z += self.velocity_z

    def up(self):
        self.velocity_z += 1

    def down(self):
        self.velocity_z -= 1

    def left(self):
        self.velocity_x -= 1

    def right(self):
        self.velocity_x += 1

    def forward(self):
        self.velocity_y += 1

    def backward(self):
        self.velocity_y -= 1

drone = Drone(0, 0, 0)

while True:
    print("Drönarens position: ({}, {}, {})".format(drone.x, drone.y, drone.z))
    action = input("Vad vill du göra? (up, down, left, right, forward, backward, fly): ")
    if action == "up":
        drone.up()
    elif action == "down":
        drone.down()
    elif action == "left":
        drone.left()
    elif action == "right":
        drone.right()
    elif action == "forward":
        drone.forward()
    elif action == "backward":
        drone.backward()
    elif action == "fly":
        drone.fly()
    else:
        print("Ogiltigt kommando")
